{#- Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/hero-split-media.json
    What HeroSplit shows beside the text: a picture, a picture with a floating card, a grid of four pictures with captions, or a picture with two plan cards floating over it.
    Props (p): content, alt, media. -#}
{%- set v_content = ui_def(p['content'], none) -%}
{%- set v_alt = ui_def(p['alt'], none) -%}
{%- set v_media = ui_def(p['media'], 'picture') -%}
{%- if ui_t(ui_eq(v_media, 'picture')) %}
  {{ ui_include('blocks/media-frame.html.j2', {'p': {'alt': v_alt, 'ratio': '4/3'}}) }}
{%- endif %}
{%- if ui_t(ui_eq(v_media, 'card')) %}
  {{ ui_include('blocks/offer-media.html.j2', {'p': {'alt': v_alt, 'card': ui_get(v_content, ['card'])}}) }}
{%- endif %}
{%- if ui_t(ui_eq(v_media, 'grid')) %}
  {%- set c_3 -%}
    {%- for v_f in ui_l(ui_get(v_content, ['features'])) %}
      {%- set v_i = loop.index0 -%}
      {%- if ui_t(ui_lt(v_i, 4)) %}
        {%- set c_2 -%}
          {{ ui_include('blocks/media-frame.html.j2', {'p': {'alt': ui_get(v_f, ['title']), 'ratio': '1/1'}}) }}
          {%- set c_1 -%}
            {{ ui_text(ui_get(v_f, ['title'])) }}
          {%- endset -%}
          {{ ui_include('ui/text/text.html.j2', {'p': {'Size': 'xs', 'Class': 'text-muted-foreground'}, 'children': c_1}) }}
        {%- endset -%}
        {{ ui_include('blocks/figure-block.html.j2', {'p': {'className': ui_cnv(['flex flex-col gap-2']), 'testid': 'hero-tile'}, 'children': c_2}) }}
      {%- endif %}
    {%- endfor %}
  {%- endset -%}
  {{ ui_include('ui/box/box.html.j2', {'p': {'Class': 'grid grid-cols-2 gap-4', 'Attrs': ui_attrs(['data-testid', 'hero-grid'])}, 'children': c_3}) }}
{%- endif %}
{%- if ui_t(ui_eq(v_media, 'plans')) %}
  {%- set c_8 -%}
    {{ ui_include('blocks/media-frame.html.j2', {'p': {'alt': v_alt, 'ratio': '4/3'}}) }}
    {%- for v_p in ui_l(ui_get(v_content, ['plans'])) %}
      {%- set v_i = loop.index0 -%}
      {%- if ui_t(ui_lt(v_i, 2)) %}
        {%- set c_7 -%}
          {%- set c_4 -%}
            {{ ui_text(ui_get(v_p, ['name'])) }}
          {%- endset -%}
          {{ ui_include('ui/text/text.html.j2', {'p': {'Size': 'sm', 'Weight': 'semibold'}, 'children': c_4}) }}
          {%- set c_6 -%}
            {{ ui_include('ui/lucide-icon/lucide-icon.html.j2', {'p': {'Name': 'check', 'Size': 16}}) }}
            {%- set c_5 -%}
              {{ ui_text(ui_get(v_p, ['tagline'])) }}
            {%- endset -%}
            {{ ui_include('ui/text/text.html.j2', {'p': {'Size': 'xs', 'Class': 'text-muted-foreground'}, 'children': c_5}) }}
          {%- endset -%}
          {{ ui_include('ui/group/group.html.j2', {'p': {'Gap': '2', 'Align': 'center'}, 'children': c_6}) }}
        {%- endset -%}
        {{ ui_include('ui/stack/stack.html.j2', {'p': {'Gap': '2', 'Class': ui_s(ui_cnv(['absolute w-48 rounded bg-card p-4 shadow-lg', ('top-8 left-4' if ui_t(ui_eq(v_i, 0)) else 'right-4 bottom-8')])), 'Attrs': ui_attrs(['data-testid', 'hero-plan'])}, 'children': c_7}) }}
      {%- endif %}
    {%- endfor %}
  {%- endset -%}
  {{ ui_include('ui/box/box.html.j2', {'p': {'Class': 'relative', 'Attrs': ui_attrs(['data-testid', 'hero-media'])}, 'children': c_8}) }}
{%- endif %}
